(function applyItemIdentity() {
  if (typeof ITEMS === 'undefined') return;
  for (const id in ITEM_IDENTITY) {
    const it = ITEMS[id];
    if (!it) continue;
    const p = ITEM_IDENTITY[id];
    for (const k in p) { if (p[k] === null) delete it[k]; else it[k] = p[k]; }
  }
})();
